#!/usr/bin/env python3
"""v2nodes AUTO — Web Dashboard v7"""

import asyncio, json, os, socket, subprocess, sys, threading, time, webbrowser
from urllib.parse import urlparse

try:
    from flask import Flask, Response, jsonify, request
except ImportError:
    print("pip install flask"); sys.exit(1)

try:
    import requests as _req
except ImportError:
    _req = None

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
try:
    import v2auto as core
except ImportError:
    print("v2auto.py not found!"); sys.exit(1)

WEB_PORT    = 8080
app         = Flask(__name__)
_lock       = threading.Lock()
_want_proxy = True
_cfg_cache  = {}
_cache_lock = threading.Lock()
FLAG_BASE   = "https://countryflagsapi.netlify.app/flag/{cc}.svg"

import base64 as _b64

_HTML_B64 = (
    ''
)

def get_html():
    # Try external file first
    _dir = os.path.dirname(os.path.abspath(__file__))
    _ext = os.path.join(_dir, "v2auto_dashboard.html")
    try:
        with open(_ext, encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        pass
    return _b64.b64decode(_HTML_B64).decode("utf-8")


# ── Interface IPs ──────────────────────────────────────────────
def get_iface_ips():
    result = [{"iface": "lo", "ip": "127.0.0.1"}]
    ifaces = {}
    try:
        out = subprocess.check_output(["ip", "-4", "addr", "show"],
                                      stderr=subprocess.DEVNULL, text=True)
        cur = None
        for line in out.splitlines():
            s = line.strip()
            if s and s[0].isdigit():
                cur = s.split(":")[1].strip().split("@")[0]
            elif s.startswith("inet ") and cur:
                ifaces[cur] = s.split()[1].split("/")[0]
    except Exception:
        pass
    if not ifaces:
        try:
            out = subprocess.check_output(["ifconfig"],
                                          stderr=subprocess.DEVNULL, text=True)
            cur = None
            for line in out.splitlines():
                if line and line[0] not in (" ", "\t"):
                    cur = line.split(":")[0].split()[0]
                elif "inet " in line and cur:
                    parts = line.strip().split()
                    for i, p in enumerate(parts):
                        if p in ("inet", "addr:") and i + 1 < len(parts):
                            ip = parts[i + 1].replace("addr:", "")
                            if "." in ip: ifaces[cur] = ip; break
        except Exception:
            pass
    for iface in ("wlan0", "wlan1"):
        if iface in ifaces:
            result.append({"iface": iface, "ip": ifaces[iface]})
    if len(result) == 1:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.connect(("8.8.8.8", 80))
            result.append({"iface": "net", "ip": s.getsockname()[0]})
            s.close()
        except Exception:
            pass
    return result

# ── IP enrichment ──────────────────────────────────────────────
def lookup_ip(host):
    r = {"country": "", "ip": host, "org": ""}
    if not _req: return r
    try:
        ip = socket.gethostbyname(host); r["ip"] = ip
        d = _req.get(
            f"http://ip-api.com/json/{ip}?fields=status,country,countryCode,org",
            timeout=6).json()
        if d.get("status") == "success":
            r["country"] = d.get("countryCode", "").upper()
            r["org"]     = d.get("org", "")
    except Exception:
        pass
    return r

def tcp_ping(host, port, timeout=4):
    try:
        ip = socket.gethostbyname(host)
        s  = socket.socket(); s.settimeout(timeout)
        t0 = time.time(); s.connect((ip, port))
        ms = int((time.time() - t0) * 1000); s.close()
        return ms
    except Exception:
        return None

def enrich_one(uri):
    try: p = urlparse(uri)
    except: return None
    host = p.hostname or ""; port = p.port or 443
    info = lookup_ip(host); cc = info["country"]
    return {
        "country":  cc,
        "flag_url": FLAG_BASE.format(cc=cc.lower()) if cc else "",
        "org":      info["org"],
        "ip":       info["ip"],
        "ping_ms":  tcp_ping(host, port) or 9999,
    }

def enrich_configs(configs):
    counters = {}; results = {}
    for uri in configs:
        try: scheme = urlparse(uri).scheme.lower()
        except: scheme = "unknown"
        counters[scheme] = counters.get(scheme, 0) + 1
        label = f"{scheme}-{counters[scheme]}"
        data  = enrich_one(uri) or {}
        results[uri] = {
            "label":    label,
            "country":  data.get("country", ""),
            "flag_url": data.get("flag_url", ""),
            "org":      data.get("org", ""),
            "ip":       data.get("ip", urlparse(uri).hostname or ""),
            "ping_ms":  data.get("ping_ms", 9999),
        }
    with _cache_lock:
        _cfg_cache.clear(); _cfg_cache.update(results)

def re_ping_all():
    with _cache_lock: uris = list(_cfg_cache.keys())
    for uri in uris:
        try: p = urlparse(uri)
        except: continue
        ms = tcp_ping(p.hostname or "", p.port or 443)
        if ms is not None:
            with _cache_lock:
                if uri in _cfg_cache: _cfg_cache[uri]["ping_ms"] = ms

def _load_saved():
    for p in (core.OUTPUT_WORKING, core.SAVE_PATH):
        if os.path.exists(p):
            try:
                with open(p) as f:
                    cfgs = [l.strip() for l in f if l.strip()]
                if cfgs: return cfgs
            except Exception: pass
    return []

# ── Pipeline launcher ──────────────────────────────────────────
def start_pipeline(do_update, use_iran, want_proxy):
    global _want_proxy
    with _lock:
        if core.pm.state == core.PipelineState.RUNNING:
            return
        # Atomically mark as RUNNING
        core.pm.state          = core.PipelineState.RUNNING
        core.pm.start_time     = time.time()
        core.pm.stop_requested = False
        core.pm.phase          = "BOOT"
        core.pm.phase_detail   = ""
        core.pm.total          = 0
        core.pm.completed      = 0
        core.pm.working_count  = 0
        core.pm.failed_count   = 0

    _want_proxy             = want_proxy
    core._use_iran_rules    = use_iran
    core.pm._use_iran_rules = use_iran
    if use_iran:
        core.download_geo_files()

    if not want_proxy:
        async def _noop(configs):
            core.log("Proxy skipped by user.", 4)
            core.pm._set(phase="DONE")
        core.proxy_phase = _noop

    def _run():
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        try:
            loop.run_until_complete(core.pipeline(skip_update=not do_update))
        except Exception as e:
            core.log(f"Pipeline error: {e}", 3)
            core.pm._set(phase="ERROR")
        finally:
            with core.pm._lock:
                if core.pm.state != core.PipelineState.STOPPED:
                    core.pm.state = core.PipelineState.COMPLETED
            core._sync()
        loop.close()

    threading.Thread(target=_run, daemon=True, name="pipeline").start()

    def _enrich():
        last = 0
        if not do_update:
            cfgs = _load_saved()
            if cfgs: enrich_configs(cfgs); last = len(cfgs)
        while not core.pm.stop_requested:
            time.sleep(4)
            cfgs = _load_saved()
            if cfgs and len(cfgs) != last:
                last = len(cfgs); enrich_configs(cfgs)
            elif cfgs and last > 0:
                time.sleep(56); re_ping_all()

    threading.Thread(target=_enrich, daemon=True, name="enrich").start()

# ── Routes ─────────────────────────────────────────────────────
@app.route("/")
def index():
    return get_html(), 200, {"Content-Type": "text/html; charset=utf-8"}

@app.route("/api/has_saved")
def api_has_saved():
    has     = os.path.exists(core.OUTPUT_WORKING) or os.path.exists(core.SAVE_PATH)
    already = core.pm.state == core.PipelineState.RUNNING
    return jsonify(has_saved=has, already_started=already)

@app.route("/api/launch", methods=["POST"])
def api_launch():
    if core.pm.state == core.PipelineState.RUNNING:
        return jsonify(ok=True, note="already running")
    try:
        d = request.get_json(force=True) or {}
        threading.Thread(
            target=start_pipeline,
            args=(bool(d.get("do_update", False)),
                  bool(d.get("use_iran_rules", False)),
                  bool(d.get("want_proxy", True))),
            daemon=True
        ).start()
        return jsonify(ok=True)
    except Exception as e:
        return jsonify(ok=False, error=str(e))

@app.route("/api/stop", methods=["POST"])
def api_stop():
    core.pm.request_stop()
    core.log("Stop requested by user.", 4)
    return jsonify(ok=True)

@app.route("/api/reset", methods=["POST"])
def api_reset():
    if core.pm.state == core.PipelineState.RUNNING:
        return jsonify(ok=False, error="Pipeline still running. Stop first.")
    core.pm.reset()
    global _want_proxy
    _want_proxy = True
    with _cache_lock: _cfg_cache.clear()
    return jsonify(ok=True)

@app.route("/api/retest", methods=["POST"])
def api_retest():
    if core.pm.state == core.PipelineState.RUNNING:
        return jsonify(ok=False, error="Pipeline still running.")
    configs = list(core.pm.working_configs) or _load_saved()
    if not configs:
        return jsonify(ok=False, error="No working configs to retest.")
    d     = request.get_json(force=True) if request.data else {}
    clear = bool((d or {}).get("clear_previous", True))

    def _run():
        loop = asyncio.new_event_loop(); asyncio.set_event_loop(loop)
        with core.pm._lock:
            core.pm.state          = core.PipelineState.RUNNING
            core.pm.start_time     = time.time()
            core.pm.stop_requested = False
        try:
            loop.run_until_complete(core.retest_phase(configs, clear_previous=clear))
        except Exception as e:
            core.log(f"Retest error: {e}", 3)
        finally:
            core.pm._set(state=core.PipelineState.COMPLETED)
            core._sync()
        loop.close()

    threading.Thread(target=_run, daemon=True).start()
    return jsonify(ok=True, retest_count=len(configs))

@app.route("/api/progress")
def api_progress():
    return jsonify(core.pm.snapshot())

@app.route("/api/proxy_config")
def api_proxy_config():
    snap = core.pm.snapshot()
    sp   = snap.get("socks_port", 10901)
    hp   = snap.get("http_port",  10801)
    dp   = core.DNS_PORT
    cfg  = {
        "_comment":    "v2auto proxy config",
        "socks5":      {"host": "127.0.0.1", "port": sp, "udp": True},
        "http_proxy":  {"host": "127.0.0.1", "port": hp},
        "dns":         {"host": "127.0.0.1", "port": dp, "protocol": "udp"},
        "env_vars":    {
            "http_proxy":  f"http://127.0.0.1:{hp}",
            "https_proxy": f"http://127.0.0.1:{hp}",
            "ALL_PROXY":   f"socks5://127.0.0.1:{sp}",
        },
        "android_wifi": {"proxy_host": "127.0.0.1", "proxy_port": hp, "dns_port": dp},
    }
    return Response(
        json.dumps(cfg, indent=2, ensure_ascii=False),
        mimetype="application/json",
        headers={"Content-Disposition": "attachment; filename=proxy_config.json"}
    )

@app.route("/stream")
def stream():
    def gen():
        while True:
            snap     = core.pm.snapshot()
            log_list = snap["log"]
            log_ver  = hash(tuple((t, m) for t, m, _ in log_list))
            with _cache_lock:
                cfgs = [
                    {"label": v["label"], "country": v["country"],
                     "flag_url": v["flag_url"], "ip": v["ip"],
                     "org": v["org"], "ping_ms": v["ping_ms"], "raw": u}
                    for u, v in sorted(_cfg_cache.items(),
                                       key=lambda x: x[1].get("ping_ms") or 9999)
                ]
            payload = {
                "state":           snap["state"],
                "phase":           snap["phase"],
                "phase_detail":    snap["phase_detail"],
                "total":           snap["total"],
                "tested":          snap["tested"],
                "working":         snap["working"],
                "failed":          snap["failed"],
                "tcp_fail":        0,
                "active_cfg":      snap["active_cfg"],
                "proxy_status":    snap["proxy_status"],
                "proxy_ms":        snap["proxy_ms"],
                "standby_count":   snap["standby_count"],
                "socks_port":      snap["socks_port"],
                "http_port":       snap["http_port"],
                "dns_port":        core.DNS_PORT,
                "iface_ips":       get_iface_ips(),
                "log":             log_list,
                "log_version":     log_ver,
                "configs":         cfgs,
                "pipeline_started":snap["pipeline_started"],
                "want_proxy":      _want_proxy,
                "workers_info":    f"{core.MAX_CONCURRENT} workers (CPU×{core._CPU_COUNT})",
                "vless_in_uuid":   core.get_or_create_uuid(),
                "vless_in_port":   core.VLESS_IN_PORT,
            }
            yield f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"
            time.sleep(0.25)

    return Response(gen(), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache",
                             "X-Accel-Buffering": "no",
                             "Connection": "keep-alive"})

# ── Boot ────────────────────────────────────────────────────────
def open_browser():
    time.sleep(1.5)
    url = f"http://127.0.0.1:{WEB_PORT}"
    for cmd in [["termux-open-url", url],
                ["am", "start", "--user", "0", "-a",
                 "android.intent.action.VIEW", "-d", url],
                ["xdg-open", url]]:
        try:
            subprocess.Popen(cmd, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL); break
        except Exception: continue
    else:
        try: webbrowser.open(url)
        except Exception: pass
    print(f"  ✓ Dashboard → {url}")

def run_flask():
    import logging
    logging.getLogger("werkzeug").setLevel(logging.ERROR)
    app.run(host="0.0.0.0", port=WEB_PORT, threaded=True, use_reloader=False)

def main():
    print(f"\n  ⚡ v2nodes AUTO — Web Dashboard  (port {WEB_PORT})")
    threading.Thread(target=run_flask,    daemon=True).start()
    threading.Thread(target=open_browser, daemon=True).start()
    print(f"  Open: http://127.0.0.1:{WEB_PORT}  |  Ctrl+C to stop\n")
    try:
        while True: time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        core.pm.request_stop()
        print("\n  Stopping..."); core.cleanup(); time.sleep(0.4)
        print("  Goodbye! ⚡"); os._exit(0)

if __name__ == "__main__":
    main()
